using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;
namespace MackieTranslator {
 public static class ReliabilityTests {
  static int count;static void Check(bool value,string name){if(!value)throw new Exception(name);count++;}
  static byte[] Encode(byte[] bytes){return new byte[]{77,84,84,69,83,84}.Concat(bytes).ToArray();}
  static byte[] Decode(byte[] bytes){if(bytes.Length<6||bytes[0]!=77)throw new InvalidDataException();return bytes.Skip(6).ToArray();}
  static async Task RunCases(string root){
   string path=Path.Combine(root,"history.dat");var journal=new TranslationJournal(path,Encode,Decode);for(int i=0;i<25;i++)journal.Add("source "+i,"译文 "+i,"test");await journal.SaveAsync();var restarted=new TranslationJournal(path,Encode,Decode);restarted.Load();Check(restarted.Entries.Length==20&&restarted.Entries[0].Source=="source 24"&&restarted.Entries[19].Source=="source 5","Twenty records restored after restart");
   var exposed=restarted.Entries;exposed[0].Source="modified";Check(restarted.Entries[0].Source=="source 24","External edits cannot mutate stored history");
   restarted.Clear();await restarted.SaveAsync();var cleared=new TranslationJournal(path,Encode,Decode);cleared.Load();Check(cleared.Entries.Length==0,"Clear survives restart");
   File.WriteAllText(path,"corrupted");var corrupt=new TranslationJournal(path,Encode,Decode);corrupt.Load();Check(corrupt.Entries.Length==0&&corrupt.LoadStatus.Contains("失败")&&File.ReadAllText(path)=="corrupted","Corrupted history handled without destroying file");
   string longPath=Path.Combine(root,"long.dat");var longJournal=new TranslationJournal(longPath,Encode,Decode);for(int i=0;i<20;i++)longJournal.Add(new string('中',59000)+i,new string('文',59000)+i,"test");await longJournal.SaveAsync();Check(new FileInfo(longPath).Length>4000000,"Long fixture exceeds old file limit");var longRestart=new TranslationJournal(longPath,Encode,Decode);longRestart.Load();Check(longRestart.Entries.Length==20,"Long twenty-record history restores");
   var started=new ManualResetEventSlim(false);var resume=new ManualResetEventSlim(false);string racePath=Path.Combine(root,"race.dat");int times=0;var racing=new TranslationJournal(racePath,data=>{if(Interlocked.Increment(ref times)==1){started.Set();if(!resume.Wait(5000))throw new TimeoutException();}return Encode(data);},Decode);racing.Add("stale","old","test");var first=racing.SaveAsync();Check(started.Wait(5000),"Save started before clear");racing.Clear();var second=racing.SaveAsync();resume.Set();await Task.WhenAll(first,second);var raceRestart=new TranslationJournal(racePath,Encode,Decode);raceRestart.Load();Check(raceRestart.Entries.Length==0,"Pending save cannot resurrect cleared history");started.Dispose();resume.Dispose();
   string blocked=Path.Combine(root,"blocked");Directory.CreateDirectory(blocked);var failing=new TranslationJournal(blocked,Encode,Decode);failing.Add("keep","retain","test");bool failed=false;try{await failing.SaveAsync();}catch{failed=true;}Check(failed&&failing.Entries.Length==1&&!File.Exists(blocked+".tmp"),"Save failure retains memory and removes temporary file");
   Check(SelectionCapture.CanContinue(true,2,2,true),"Current selection accepted");Check(!SelectionCapture.CanContinue(false,2,2,true),"Pause cancels reading");Check(!SelectionCapture.CanContinue(true,3,2,true),"New gesture rejects stale text");Check(!SelectionCapture.CanContinue(true,2,2,false),"Leaving target cancels capture");Check(SelectionCapture.IsSelectionGesture(-12,0,false)&&SelectionCapture.IsSelectionGesture(0,0,true)&&!SelectionCapture.IsSelectionGesture(0,0,false),"Drag/double click versus plain click");
   int encodes=0;string retryPath=Path.Combine(root,"retry.dat");var retry=new TranslationJournal(retryPath,data=>{if(Interlocked.Increment(ref encodes)==1)throw new IOException("synthetic failure");return Encode(data);},Decode);retry.Add("retry","保留","test");try{await retry.SaveAsync();}catch(IOException){}await retry.SaveAsync();var retryRestart=new TranslationJournal(retryPath,Encode,Decode);retryRestart.Load();Check(retryRestart.Entries.Length==1,"Save can be retried after failure");
   string invalidPath=Path.Combine(root,"invalid.dat");File.WriteAllBytes(invalidPath,Encode(Encoding.UTF8.GetBytes("[{}]")));var invalid=new TranslationJournal(invalidPath,Encode,Decode);invalid.Load();Check(invalid.Entries.Length==0&&invalid.LoadStatus.Contains("失败"),"Invalid record schema does not enter history");
   LocalDiagnostics.Record(CaptureStep.CopyShortcut);string report=LocalDiagnostics.Report(false,20);Check(report.Contains(BuildInfo.Version)&&!report.Contains("source 24")&&!report.Contains("译文 24"),"Diagnostic report omits journal content");
  }
  public static int Run(){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"reliability-"+Guid.NewGuid().ToString("N"));var report=new StringBuilder();try{Directory.CreateDirectory(root);RunCases(root).GetAwaiter().GetResult();report.AppendLine(count+" reliability checks passed.");try{string secret="synthetic history test";byte[] encrypted=ProtectedData.Protect(Encoding.UTF8.GetBytes(secret),null,DataProtectionScope.CurrentUser);Check(Encoding.UTF8.GetString(ProtectedData.Unprotect(encrypted,null,DataProtectionScope.CurrentUser))==secret,"Real DPAPI round trip");report.AppendLine("Real Windows DPAPI round trip passed.");string encryptedPath=Path.Combine(root,"protected-history.dat");Func<byte[],byte[]> enc=data=>ProtectedData.Protect(data,null,DataProtectionScope.CurrentUser),dec=data=>ProtectedData.Unprotect(data,null,DataProtectionScope.CurrentUser);var real=new TranslationJournal(encryptedPath,enc,dec);real.Add(secret,"合成测试译文","test");real.SaveAsync().GetAwaiter().GetResult();var realRestart=new TranslationJournal(encryptedPath,enc,dec);realRestart.Load();Check(realRestart.Entries.Length==1&&realRestart.Entries[0].Source==secret&&!Encoding.UTF8.GetString(File.ReadAllBytes(encryptedPath)).Contains(secret),"Encrypted history survives restart without plaintext file");real.Clear();real.SaveAsync().GetAwaiter().GetResult();var realCleared=new TranslationJournal(encryptedPath,enc,dec);realCleared.Load();Check(realCleared.Entries.Length==0,"Encrypted history clear survives restart");report.AppendLine("Real encrypted history save/restart/clear passed.");}catch(CryptographicException){report.AppendLine("Windows DPAPI round trip unavailable in this environment; file/race tests used an explicit test codec, never a production fallback.");}return 0;}catch(Exception error){report.AppendLine("FAILED: "+error);return 1;}finally{File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"reliability-test-result.txt"),"Total checks completed: "+count+"\n"+report.ToString());string absolute=Path.GetFullPath(root);if(absolute.StartsWith(Path.GetFullPath(AppDomain.CurrentDomain.BaseDirectory),StringComparison.OrdinalIgnoreCase)&&Directory.Exists(absolute))Directory.Delete(absolute,true);}}
 }
}
